import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:go_router/go_router.dart';
import 'package:hugeicons/hugeicons.dart';

class ProbeCounter extends Notifier<int> {
  @override
  int build() => 0;

  void increment() => state++;
}

final counterProvider = NotifierProvider<ProbeCounter, int>(ProbeCounter.new);

final routerProvider = Provider<GoRouter>((ref) {
  final router = GoRouter(
    routes: [
      GoRoute(path: '/', builder: (context, state) => const ProbeHome()),
      GoRoute(
        path: '/detail',
        builder: (context, state) => const ProbeDetail(),
      ),
    ],
  );
  ref.onDispose(router.dispose);
  return router;
});

class ProbeApp extends ConsumerWidget {
  const ProbeApp({super.key, this.mode = ThemeMode.system, this.textScale = 1});

  final ThemeMode mode;
  final double textScale;

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return MaterialApp.router(
      debugShowCheckedModeBanner: false,
      theme: ThemeData(brightness: Brightness.light),
      darkTheme: ThemeData(brightness: Brightness.dark),
      themeMode: mode,
      routerConfig: ref.watch(routerProvider),
      builder: (context, child) => MediaQuery(
        data: MediaQuery.of(context)
            .copyWith(textScaler: TextScaler.linear(textScale)),
        child: child!,
      ),
    );
  }
}

class ProbeHome extends ConsumerWidget {
  const ProbeHome({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    final count = ref.watch(counterProvider);
    return Scaffold(
      body: SafeArea(
        child: LayoutBuilder(
          builder: (context, constraints) {
            final window = switch (constraints.maxWidth) {
              < 600 => 'Small',
              < 840 => 'Medium',
              < 1200 => 'Large',
              _ => 'Largest',
            };
            return SingleChildScrollView(
              padding: const EdgeInsets.all(24),
              child: Column(
                children: [
                  Text('Window: $window'),
                  Text('Count: $count'),
                  TextButton(
                    onPressed: () =>
                        ref.read(counterProvider.notifier).increment(),
                    style: TextButton.styleFrom(
                      minimumSize: const Size(48, 48),
                    ),
                    child: const Row(
                      mainAxisSize: MainAxisSize.min,
                      children: [
                        ExcludeSemantics(
                          child: HugeIcon(icon: HugeIcons.strokeRoundedAdd01),
                        ),
                        SizedBox(width: 8),
                        Text('Increase'),
                      ],
                    ),
                  ),
                  TextButton(
                    onPressed: () => context.go('/detail'),
                    child: const Text('Open detail'),
                  ),
                ],
              ),
            );
          },
        ),
      ),
    );
  }
}

class ProbeDetail extends ConsumerWidget {
  const ProbeDetail({super.key});

  @override
  Widget build(BuildContext context, WidgetRef ref) {
    return Scaffold(
      body: Column(
        children: [
          Text('Detail count: ${ref.watch(counterProvider)}'),
          TextButton(
            onPressed: () => context.go('/'),
            child: const Text('Return'),
          ),
        ],
      ),
    );
  }
}

