import 'package:dio/dio.dart';
import 'package:drift/drift.dart' show Variable;
import 'package:flutter/material.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:hugeicons/hugeicons.dart';
import 'package:json_annotation/json_annotation.dart';
import 'package:isolated_probe/probe_app.dart';
import 'package:isolated_probe/probe_database.dart';
import 'package:isolated_probe/probe_models.dart';

void main() {
  test('generated DTO preserves an exact synthetic string and null', () {
    const fixture = ProbeDto(exactMinor: '9007199254740993');
    final restored = ProbeDto.fromJson(fixture.toJson());
    expect(restored.exactMinor, '9007199254740993');
    expect(restored.note, isNull);
    expect(fixture.toJson().containsKey('note'), isTrue);
  });

  test('checked DTO rejects a numeric value for its string field', () {
    expect(
      () => ProbeDto.fromJson({'exactMinor': 12}),
      throwsA(isA<CheckedFromJsonException>()),
    );
  });

  test(
    'generated Drift row and insert companion compile without opening a DB',
    () {
      const row = ProbeRecord(id: 1, label: 'Synthetic');
      expect(ProbeRecord.fromJson(row.toJson()).label, 'Synthetic');
      final columns = ProbeRowsCompanion.insert(label: 'Synthetic')
          .toColumns(false);
      expect((columns['label']! as Variable<String>).value, 'Synthetic');
      expect(columns.containsKey('id'), isFalse);
    },
  );

  test('Dio intercepts a synthetic request without network access', () async {
    final dio = Dio(BaseOptions(baseUrl: 'https://probe.invalid'));
    addTearDown(() => dio.close(force: true));
    dio.interceptors.add(
      InterceptorsWrapper(
        onRequest: (options, handler) {
          expect(options.path, '/synthetic');
          handler.resolve(
            Response<Map<String, dynamic>>(
              requestOptions: options,
              statusCode: 200,
              data: {'exact': '9007199254740993'},
            ),
          );
        },
      ),
    );
    final response = await dio.get<Map<String, dynamic>>('/synthetic');
    expect(response.data?['exact'], '9007199254740993');
  });

  test('independent Riverpod containers do not share synthetic state', () {
    final first = ProviderContainer();
    final second = ProviderContainer();
    addTearDown(first.dispose);
    addTearDown(second.dispose);
    first.read(counterProvider.notifier).increment();
    expect(first.read(counterProvider), 1);
    expect(second.read(counterProvider), 0);
  });

  testWidgets(
    'router, rounded icon, theme and width changes retain scoped state',
    (tester) async {
      tester.view.devicePixelRatio = 1;
      tester.view.physicalSize = const Size(390, 844);
      addTearDown(tester.view.resetPhysicalSize);
      addTearDown(tester.view.resetDevicePixelRatio);
      await tester.pumpWidget(const ProviderScope(child: ProbeApp()));
      await tester.pumpAndSettle();
      expect(find.byType(HugeIcon), findsOneWidget);
      await tester.tap(find.text('Increase'));
      await tester.pumpAndSettle();
      expect(find.text('Count: 1'), findsOneWidget);
      for (final mode in [ThemeMode.light, ThemeMode.dark]) {
        for (final size in [
          (390.0, 'Small'),
          (700.0, 'Medium'),
          (1000.0, 'Large'),
          (1300.0, 'Largest'),
        ]) {
          tester.view.physicalSize = Size(size.$1, 844);
          await tester.pumpWidget(
            ProviderScope(child: ProbeApp(mode: mode, textScale: 2)),
          );
          await tester.pumpAndSettle();
          expect(find.text('Window: ${size.$2}'), findsOneWidget);
          expect(find.text('Count: 1'), findsOneWidget);
          expect(tester.takeException(), isNull);
          final context = tester.element(find.byType(ProbeHome));
          expect(
            Theme.of(context).brightness,
            mode == ThemeMode.dark ? Brightness.dark : Brightness.light,
          );
        }
      }
      await tester.tap(find.text('Open detail'));
      await tester.pumpAndSettle();
      expect(find.text('Detail count: 1'), findsOneWidget);
      await tester.tap(find.text('Return'));
      await tester.pumpAndSettle();
      expect(find.text('Count: 1'), findsOneWidget);
      await tester.pumpWidget(const SizedBox.shrink());
      await tester.pumpAndSettle();
    },
  );
}
